package org.credivel.news;
import java.text.Normalizer;import java.time.Instant;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NewsService{private final NewsRepository repo;public NewsService(NewsRepository r){repo=r;}public Page<NewsResponse> list(int page,int size){return repo.findByStatus(NewsStatus.PUBLISHED,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"publishedAt"))).map(NewsResponse::from);}@Transactional public NewsResponse bySlug(String slug){News n=repo.findBySlugAndStatus(slug,NewsStatus.PUBLISHED).orElseThrow(NewsNotFoundException::new);n.setViews(n.getViews()+1);return NewsResponse.from(n);}@Transactional public NewsResponse byId(Long id){News n=repo.findById(id).filter(x->x.getStatus()==NewsStatus.PUBLISHED).orElseThrow(NewsNotFoundException::new);n.setViews(n.getViews()+1);return NewsResponse.from(n);}@Transactional public NewsResponse create(NewsRequest r){News n=new News();apply(n,r);return NewsResponse.from(repo.save(n));}@Transactional public NewsResponse update(Long id,NewsRequest r){News n=repo.findById(id).orElseThrow(NewsNotFoundException::new);apply(n,r);return NewsResponse.from(n);}public void delete(Long id){if(!repo.existsById(id))throw new NewsNotFoundException();repo.deleteById(id);}private void apply(News n,NewsRequest r){n.setTitle(r.title().trim());n.setSlug(slugify(r.slug()==null||r.slug().isBlank()?r.title():r.slug()));n.setSummary(r.summary().trim());n.setContent(r.content().trim());n.setImageUrl(r.imageUrl().trim());n.setClassification(r.classification());n.setSource(r.source().trim());n.setAuthor(r.author()==null||r.author().isBlank()?null:r.author().trim());n.setCategory(r.category().trim());n.setStatus(r.status());n.setPublishedAt(r.status()==NewsStatus.PUBLISHED?(r.publishedAt()==null?Instant.now():r.publishedAt()):r.publishedAt());}private String slugify(String v){String s=Normalizer.normalize(v,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");return s.isBlank()?"noticia":s;}}
